//! 🧳️ Native receiving keeps its exact original source until the receiver and staged output settle.
use super::{NativeReceive,NativeReceiver};
use crate::{NativeDecodeControl,RetirementDemand,ValueError,ValueRefusalKind,retirement::{RetireOwned,RetirementCursor,RetirementStep},retained_clone::{RetainedCloneSource,RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
/// 🪪️ The registered codec supplies its genuine typed input source and required receiver without a cold conversion.
pub struct NativeReceivingOriginal<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync=I>{original:ManuallyDrop<Option<RetainedCloneSource<I,A>>>,receiver:ManuallyDrop<Option<Box<T::Receiver>>>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native original receiving is not in the required funded phase")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(copy_bytes:usize)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:copy_bytes,..Default::default()}}
fn nested(mut d:RetirementDemand,copy:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(copy).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> NativeReceivingOriginal<I,T,A>{
 pub fn shell_demand()->RetirementDemand{fixed(size_of::<Self>())}
 pub fn begin_shell(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::shell_demand();if !retained_clone_grant_admits(g,d){return Err(invalid());}Ok((Self{original:ManuallyDrop::new(None),receiver:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),closing:false},receipt(d.copy_bytes)))}
 pub fn original_capture_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.original.is_some()||self.receiver.is_some()||self.output.is_some(){return Err(invalid());}Ok(fixed(2*size_of::<Option<RetainedCloneSource<I,A>>>()))}
 pub fn admit_original(&mut self,original:&mut Option<RetainedCloneSource<I,A>>,g:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{let d=self.original_capture_demand()?;if !retained_clone_grant_admits(g,d){return Ok(Default::default());}if original.is_none(){return Err(invalid());}*self.original=original.take();Ok(receipt(d.copy_bytes))}
 pub fn receiver_birth_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.original.is_none()||self.receiver.is_some()||self.output.is_some(){return Err(invalid());}let mut d=nested(T::receive_birth_demand(),size_of::<T::Receiver>()+2*size_of::<Option<Box<T::Receiver>>>())?;d.capacity_bytes=d.capacity_bytes.checked_add(size_of::<T::Receiver>()).ok_or_else(invalid)?;Ok(d)}
 pub fn begin_receiver(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{let d=self.receiver_birth_demand()?;if !retained_clone_grant_admits(g,d){return Ok(Default::default());}let capacity=size_of::<T::Receiver>();let overhead=capacity+2*size_of::<Option<Box<T::Receiver>>>();let(receiver,mut p)=T::begin_receive(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-overhead,maximum_capacity_bytes:g.maximum_capacity_bytes-capacity,maximum_depth:g.maximum_depth-1,..g})?;*self.receiver=Some(Box::new(receiver));p.copied_bytes=p.copied_bytes.checked_add(overhead).ok_or_else(invalid)?;p.retained_capacity_bytes=p.retained_capacity_bytes.checked_add(capacity).ok_or_else(invalid)?;crate::retained_clone::admit_retained_clone_progress(g,p,"native original receiver birth").map_err(|error|error.with_retained_progress(p))}
 pub fn constructor_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()+size_of::<RetainedCloneSource<I,A>>()+size_of::<T::Receiver>()+2*size_of::<Option<Box<T::Receiver>>>(),capacity_bytes:size_of::<T::Receiver>(),depth:2,..Default::default()}}
 pub fn admit_parts(original:RetainedCloneSource<I,A>,receiver:T::Receiver,g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),(ValueError,RetainedCloneSource<I,A>,T::Receiver)>{let d=Self::constructor_demand();if !retained_clone_grant_admits(g,d){return Err((invalid(),original,receiver));}let mut p=receipt(d.copy_bytes);p.retained_capacity_bytes=d.capacity_bytes;Ok((Self{original:ManuallyDrop::new(Some(original)),receiver:ManuallyDrop::new(Some(Box::new(receiver))),output:ManuallyDrop::new(None),retirement:Default::default(),closing:false},p))}
 pub fn borrow_input(&self)->Result<RetainedCloneRef<'_,I>,ValueError>{if self.closing{return Err(invalid());}self.original.as_ref().ok_or_else(invalid)?.try_borrow()}
 pub fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid());}let receiver=self.receiver.as_ref().ok_or_else(invalid)?;let overhead=size_of::<Option<T>>();let d=if receiver.output_ready(){receiver.take_demand()?}else{receiver.demands(self.borrow_input()?,body)?};nested(d,overhead)}
 pub fn advance(&mut self,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demands(body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}let overhead=size_of::<Option<T>>();let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-overhead,maximum_depth:g.maximum_depth-1,..g};let receiver=self.receiver.as_mut().ok_or_else(invalid)?;let mut p=if receiver.output_ready(){let(value,p)=receiver.take(child)?.ok_or_else(invalid)?;*self.output=Some(value);p}else{receiver.advance(self.original.as_ref().ok_or_else(invalid)?.try_borrow()?,control,body,child)?.progress()};p.copied_bytes=p.copied_bytes.checked_add(overhead).ok_or_else(invalid)?;crate::retained_clone::admit_retained_clone_progress(g,p,"native original receiving")?;Ok(if self.output.is_some(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid());}Ok(fixed(2*size_of::<Option<T>>()))}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(T,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None);}Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d.copy_bytes))))}
 pub fn begin_close(&mut self){self.closing=true;if let Some(receiver)=self.receiver.as_mut(){receiver.begin_close();}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if let Some(receiver)=self.receiver.as_ref(){return if receiver.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:2*size_of::<Option<Box<T::Receiver>>>(),release_bytes:size_of::<T::Receiver>(),depth:1,..Default::default()})}else{nested(receiver.close_demands(body)?,0)};}if !self.retirement.is_empty(){return nested(self.retirement.next_owner_demands::<T>(false,&None,body)?,0);}if self.output.is_some(){return nested(self.retirement.next_owner_demands::<T>(true,&None,body)?,0);}if let Some(original)=self.original.as_ref(){return if original.terminal_is_empty(){Ok(fixed(2*size_of::<Option<RetainedCloneSource<I,A>>>()))}else{nested(original.next_close_demand(body)?,0)};}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};if let Some(receiver)=self.receiver.as_mut(){if !receiver.terminal_is_empty(){return receiver.close_step(child).map(|s|RetainedCloneStep::Progress(s.progress()));}drop(self.receiver.take());let mut p=receipt(d.copy_bytes);p.released_bytes=d.release_bytes;return Ok(RetainedCloneStep::Progress(p));}if !self.retirement.is_empty(){return self.retirement.step_granted(child).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(step)=self.retirement.begin_granted(&mut self.output,child)?{return Ok(RetainedCloneStep::Progress(step.progress()));}if let Some(original)=self.original.as_mut(){if !original.terminal_is_empty(){return original.close_step(child).map(|s|RetainedCloneStep::Progress(s.progress()));}self.original.take();return Ok(RetainedCloneStep::Complete(receipt(d.copy_bytes)));}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.receiver.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.original.is_none()}
}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetireOwned for NativeReceivingOriginal<I,T,A>{fn retirement(mut self)->Box<dyn RetirementCursor>{self.begin_close();Box::new(self)}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<Self>())}fn controlled_retirement_supported()->bool{true}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetirementCursor for NativeReceivingOriginal<I,T,A>{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close_demands(body)}fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{match Self::close_step(self,g){Ok(s)=>RetirementStep::Progress(s.progress()),Err(error)=>RetirementStep::Failure(error)}}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}fn terminal_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> Drop for NativeReceivingOriginal<I,T,A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native receiving keeps original custody until funded closure");}}
